import{c as o,Q as a,j as t,m as i}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse('{"title":"QR code sign-in","description":"Sign in to GateKeeper by scanning a QR code with your phone.","frontmatter":{"title":"QR code sign-in","description":"Sign in to GateKeeper by scanning a QR code with your phone."},"headers":[],"relativePath":"auth/qr-login.md","filePath":"auth/qr-login.md"}'),n={name:"auth/qr-login.md"};function r(s,e,c,p,d,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<p>QR code sign-in lets you authenticate on a PC or shared device by scanning a code with your phone. You approve the login on your phone, and the other device signs in automatically - no password or email code required.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>On the device you want to sign in to, open the GateKeeper login page and click the <strong>QR code</strong> tab.</li><li>A QR code appears. Open your phone&#39;s camera and scan it.</li><li>Your browser opens a GateKeeper approval page. If your phone does not already have an active GateKeeper session, you are asked to sign in first.</li><li>Tap <strong>Approve sign-in</strong>. Your phone shows a confirmation.</li><li>The PC detects the approval and signs you in automatically.</li></ol><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>Your phone must have an active GateKeeper session. Sign in on your phone once using any method (password, passkey, or email code). After that you can use QR sign-in to authenticate on any other device without re-entering credentials.</p><h2 id="qr-code-expiry" tabindex="-1">QR code expiry <a class="header-anchor" href="#qr-code-expiry" aria-label="Permalink to &quot;QR code expiry&quot;">​</a></h2><p>Each QR code is valid for 5 minutes. If it expires before you scan it, a new code loads automatically after a short pause.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>The QR code encodes a one-time token. Approving the token creates a new session on the device that displayed the code. The token is deleted from the database once it is used or after it expires.</p><p>Only approve a sign-in if you were the one who opened the QR code tab. If you receive the approval page unexpectedly, tap <strong>Deny</strong> to close it without approving.</p>',10)])])}const y=o(n,[["render",r]]);export{u as __pageData,y as default};
